package com.example.acres.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.security.*; import java.util.*;
@Component public class AuthCsrfFilter extends OncePerRequestFilter { private static final String COOKIE="XSRF-TOKEN", HEADER="X-XSRF-TOKEN"; protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{ String path=req.getRequestURI(); boolean protectedPath=path.startsWith("/api/auth/") && Set.of("POST").contains(req.getMethod()) && !path.equals("/api/auth/csrf"); if(protectedPath){String cookie=null;if(req.getCookies()!=null)for(Cookie c:req.getCookies())if(COOKIE.equals(c.getName()))cookie=c.getValue();String header=req.getHeader(HEADER);if(cookie==null||header==null||!MessageDigest.isEqual(cookie.getBytes(),header.getBytes())){res.setStatus(403);res.setContentType("application/json");res.getWriter().write("{\"status\":403,\"error\":\"CSRF\",\"message\":\"CSRF validation failed\"}");return;}} chain.doFilter(req,res);} }
